const $=s=>document.querySelector(s),fmt=n=>n.toLocaleString('ko-KR');
const end='2026-10-23',dayMS=86400000,date=i=>new Date(Date.parse(end+'T00:00:00Z')+i*dayMS).toISOString().slice(0,10);
let days=7,channel='all',sort='views',target=10000;try{target=Number(localStorage.getItem('pulse-goal-2026-10-19'))||10000}catch{}
const titles=['퇴근 후, 나를 위한 작은 루틴','오늘도 한 걸음 나아가는 법','일주일을 바꾸는 3가지 습관','이 순간이 필요한 당신에게','조금 느려도 괜찮아','테포의 하루, 함께해요','작은 도전이 만드는 변화','당신의 월요일을 응원해요'];
const contents=Array.from({length:40},(_,i)=>({id:i+1,title:titles[i%8],channel:i%2?'YouTube':'Instagram',date:date(-Math.floor(i*1.5)),valid:i%13!==12,thumbnail:'thumbnails/'+(i%8)+'.svg',emoji:['🌿','☕','📖','🌅','🎧','🪴','✨','🍃'][i%8],type:i%2?'Shorts':'릴스'}));
const data=[];for(let d=-59;d<=0;d++)for(let c=0;c<2;c++){let ch=c?'YouTube':'Instagram',active=contents.filter(x=>x.channel===ch&&x.valid&&x.date<=date(d));let views=Math.round((c?540:720)*(1+.27*Math.sin(d*.9+c))*(1+(d+59)/180));let weights=active.map(x=>1/(2+(Date.parse(date(d))-Date.parse(x.date))/dayMS));let sum=weights.reduce((a,b)=>a+b,0);let allocated=0;active.forEach((x,j)=>{let v=j===active.length-1?views-allocated:Math.floor(views*weights[j]/sum);allocated+=v;data.push({date:date(d),channel:ch,content_id:x.id,views:v,likes:Math.floor(v*.031),saves:ch==='Instagram'?Math.floor(v*.013):0,shares:Math.floor(v*.007),reposts:ch==='Instagram'?Math.floor(v*.004):0,comments:Math.floor(v*.006)})})}
data.forEach(x=>x.conversions=x.likes+x.saves+x.shares+x.reposts);
const sum=(rs,k)=>rs.reduce((a,x)=>a+x[k],0),inRange=(x,n=days)=>x.date>=date(1-n)&&x.date<=end,week=data.filter(x=>x.date>='2026-10-19');
const weekly=Array.from({length:4},(_,i)=>sum(data.filter(x=>x.date>=date(-11-7*i)&&x.date<=date(-5-7*i)),'views')),avg=weekly.reduce((a,b)=>a+b,0)/4,recommended=Math.ceil(avg*1.1/100)*100;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600)}
function goal(){let v=sum(week,'views'),p=v/target*100;$('#goalLabel').textContent=fmt(target);$('#weekViews').textContent=fmt(v);$('#target').textContent=fmt(target);$('#percent').textContent=p.toFixed(1)+'% 달성';$('#progress').style.width=Math.min(p,100)+'%';$('#remaining').textContent=v>=target?'목표 달성! 이번 주의 성장을 축하해요.':'목표까지 '+fmt(target-v)+'회 남았어요 · 10.23까지 누적';$('#recommended').textContent=fmt(recommended)+'회';$('#reason').textContent='최근 4개 완료 주 평균 '+fmt(Math.round(avg))+'회 대비 10% 성장 목표예요. (100회 단위 올림)'}
function saveGoal(t){target=t;try{localStorage.setItem('pulse-goal-2026-10-19',t)}catch{toast('저장 공간을 사용할 수 없어 현재 화면에만 적용합니다.')}goal()}
function download(name,rows){if(!rows.length)return toast('다운로드할 데이터가 없습니다.');let keys=Object.keys(rows[0]),esc=v=>'"'+String(v??'').replaceAll('"','""')+'"',csv='\uFEFF'+[keys,...rows.map(r=>keys.map(k=>r[k]))].map(r=>r.map(esc).join(',')).join('\r\n');let u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=u;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('CSV 파일을 다운로드했습니다.')}
function metrics(ch){let r=data.filter(x=>inRange(x)&&x.channel===ch),prev=data.filter(x=>x.channel===ch&&x.date>=date(1-days*2)&&x.date<=date(-days));return{channel:ch,followers:ch==='Instagram'?3248:1876,posts:contents.filter(x=>x.valid&&x.channel===ch&&inRange(x)).length,views:sum(r,'views'),conversions:sum(r,'conversions'),comments:sum(r,'comments'),prev}}
function contentRows(){return contents.filter(x=>x.valid&&(channel==='all'||x.channel===channel)).map(x=>{let r=data.filter(r=>r.content_id===x.id&&inRange(r));return{...x,views:sum(r,'views'),conversions:sum(r,'conversions'),comments:sum(r,'comments')}}).filter(x=>x.views>0).sort((a,b)=>b[sort]-a[sort])}
function render(){let start=date(1-days);$('#range').textContent=start.replaceAll('-','.')+' – '+end.replaceAll('-','.');$('#channels').innerHTML=['Instagram','YouTube'].map(ch=>{let m=metrics(ch);let fields=[['followers','팔로워 / 구독자'],['posts','유효 게시글'],['views','조회수'],['conversions','전환수'],['comments','댓글 수']];return '<article class="channel '+(ch==='YouTube'?'youtube':'')+'"><div class="channeltop"><div class="channelicon">'+(ch==='Instagram'?'◎':'▶')+'</div><div><b>'+ch+'</b><small>@tepo.studio · '+(ch==='Instagram'?'인스타그램':'유튜브')+'</small></div><button data-export="'+ch+'">↓ CSV</button></div><div class="metrics">'+fields.map(([k,l])=>{let previous=k==='followers'?m[k]-days*(ch==='Instagram'?8:5):k==='posts'?contents.filter(x=>x.valid&&x.channel===ch&&x.date>=date(1-days*2)&&x.date<=date(-days)).length:sum(m.prev,k);let change=previous?((m[k]-previous)/previous*100):null;return '<div class="metric"><span>'+l+'</span><strong>'+fmt(m[k])+'</strong><small class="'+(change<0?'down':'')+'">'+(days===60?'전체 데이터 기준':change===null?'비교 데이터 없음':(change>=0?'↗ +':'↘ ')+change.toFixed(1)+'% 이전 기간 대비')+'</small></div>'}).join('')+'</div></article>'}).join('');document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>{let m=metrics(b.dataset.export);delete m.prev;download(b.dataset.export+'-summary-'+days+'days',[{기간시작:start,기간종료:end,...m}])});let rows=contentRows();$('#contentCount').textContent=rows.length;$('#rows').innerHTML=rows.map(x=>'<tr><td><span class="thumb"><img src="'+x.thumbnail+'" alt="'+x.title+' 데모 썸네일" loading="lazy" width="128" height="72"><span class="thumb-type">'+x.type+'</span></span><div>'+x.title+'<small>'+x.date.replaceAll('-','.')+' · '+x.type+'</small></div></td><td><span class="channelbadge '+(x.channel==='YouTube'?'yt':'')+'">'+x.channel+'</span></td><td><b>'+fmt(x.views)+'</b></td><td>'+fmt(x.conversions)+'</td><td>'+fmt(x.comments)+'</td><td>'+((x.conversions+x.comments)/x.views*100).toFixed(1)+'%</td></tr>').join('');chart()}
function chart(){let n=days,vals=['Instagram','YouTube'].map(ch=>Array.from({length:n},(_,i)=>sum(data.filter(x=>x.date===date(i+1-n)&&x.channel===ch),'views'))),max=Math.ceil(Math.max(...vals.flat())/500)*500,w=900,h=130;let svg='<svg viewBox="0 0 950 175" role="img" aria-label="선택 기간 일별 인스타그램 및 유튜브 조회수 추이">';for(let i=0;i<=3;i++){let y=10+i*h/3;svg+='<line x1="40" x2="940" y1="'+y+'" y2="'+y+'" stroke="#edf0e9" stroke-dasharray="3 5"/><text x="0" y="'+(y+4)+'">'+Math.round(max*(1-i/3))+'</text>'}vals.forEach((v,k)=>{let points=v.map((y,i)=>(40+(n===1?w/2:i*w/(n-1)))+','+(10+h-y/max*h)).join(' ');svg+='<polyline points="'+points+'" fill="none" stroke="'+(k?'#b5ca90':'#448267')+'" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>';if(n===1)svg+='<circle cx="490" cy="'+(10+h-v[0]/max*h)+'" r="4" fill="'+(k?'#b5ca90':'#448267')+'"/>'});[...new Set([0,Math.floor((n-1)/2),n-1])].forEach(i=>svg+='<text x="'+(40+(n===1?w/2:i*w/(n-1)))+'" y="168" text-anchor="middle">'+date(i+1-n).slice(5).replace('-','.')+'</text>');$('#chart').innerHTML=svg+'</svg>'}
$('#period').onclick=e=>{if(!e.target.dataset.days)return;days=+e.target.dataset.days;$('#period .selected').classList.remove('selected');e.target.classList.add('selected');render()};$('#channelFilter').onclick=e=>{if(!e.target.dataset.channel)return;channel=e.target.dataset.channel;$('#channelFilter .selected').classList.remove('selected');e.target.classList.add('selected');render()};$('#sort').onchange=e=>{sort=e.target.value;render()};$('#editgoal').onclick=()=>{$('#goalInput').value=target;$('#goalDialog').showModal()};$('#cancel').onclick=()=>$('#goalDialog').close();$('#goalForm').onsubmit=e=>{e.preventDefault();saveGoal(+$ ('#goalInput').value);$('#goalDialog').close();toast('이번 주 목표를 저장했습니다.')};$('#usegoal').onclick=()=>{saveGoal(recommended);toast('추천 목표를 적용했습니다.')};$('#contentcsv').onclick=()=>download('content-'+days+'days',contentRows().map(({emoji,valid,...x})=>({기간시작:date(1-days),기간종료:end,...x})));$('#allcsv').onclick=()=>download('social-pulse-daily-data',data.map(x=>({...x,content_title:contents.find(c=>c.id===x.content_id).title,weekly_target:target})));function route(){let up=location.hash==='#updates';$('#dashboard').hidden=up;$('#updates').hidden=!up;$('#breadcrumb').textContent=up?'업데이트 기록':'성과 대시보드';document.querySelectorAll('.nav').forEach(a=>a.classList.toggle('active',a.hash===(up?'#updates':'#dashboard')))}window.onhashchange=route;goal();render();route();
